constraints:
1 ≤ N ≤ 10^{4}
1 ≤ arr[i] ≤ 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def recreationalSpot(self, arr, n):
		k = -10 ** 9
		s = []
		for i in range(n - 1, -1, -1):
			if arr[i] < k:
				return True
			else:
				while len(s) != 0 and arr[i] > s[-1]:
					k = s[-1]
					s.pop()
			s.append(arr[i])
		return False
